DROP TABLE IF EXISTS responses;
DROP TABLE IF EXISTS questions;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS rounds;
DROP TABLE IF EXISTS students;
DROP TABLE IF EXISTS plans;
DROP TABLE IF EXISTS settings;
CREATE TABLE plans (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, active INTEGER DEFAULT 1);
CREATE TABLE rounds (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, sort INTEGER DEFAULT 0);
CREATE TABLE questions ( id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER, category_id INTEGER, role TEXT NOT NULL DEFAULT 'both', text TEXT NOT NULL, sort INTEGER DEFAULT 0, active INTEGER DEFAULT 1 );
CREATE TABLE students (student_id TEXT PRIMARY KEY, name TEXT, class TEXT, plan_id INTEGER, prefix TEXT, first_name TEXT, last_name TEXT, grade TEXT, room TEXT, seq INTEGER);
CREATE TABLE responses ( id INTEGER PRIMARY KEY AUTOINCREMENT, round_id INTEGER NOT NULL, student_id TEXT NOT NULL, plan_id INTEGER NOT NULL, role TEXT NOT NULL, class TEXT, answers TEXT NOT NULL, comment TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(round_id, student_id, role) );
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);
